#!/usr/bin/env python3
"""Build the static VNL feature page from the manually maintained yearly JSON."""
from __future__ import annotations

import argparse
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DEFAULT_DATA = ROOT / "docs/data/dvv_vnl_2026.json"
DEFAULT_OUTPUT = ROOT / "docs/dvv_vnl_2026.html"


def esc(value: object) -> str:
    return html.escape(str(value), quote=True)


def render_games(weeks: list[dict]) -> str:
    rows = []
    for week in weeks:
        for game in week["games"]:
            win = game["result"].startswith("3:")
            classes = "game win" if win else "game loss"
            if game.get("featured"): classes += " featured"
            sets = " · ".join(game["sets"])
            rows.append(f'''<article class="{classes}" data-week="{esc(week['id'])}">
              <div class="game-head"><span class="week-tag">{esc(week['label'])}</span><strong class="score">{esc(game['result'])}</strong></div>
              <h3>Deutschland – {esc(game['opponent'])}</h3><p class="sets">{esc(sets)}</p><p>{esc(game['note'])}</p>
            </article>''')
    return "\n".join(rows)


def render_players(players: list[dict]) -> str:
    cards = []
    for player in players:
        source = f'<a href="{esc(player["source"])}" target="_blank" rel="noopener">Profil bei Volleyball World</a>' if player.get("source") else ""
        cards.append(f'''<details class="player" data-club="{esc(player['club'])}">
          <summary><span><strong>{esc(player['name'])}</strong><small>{esc(player['position'])} · {esc(player['club'])}</small></span><span class="plus" aria-hidden="true">+</span></summary>
          <div class="player-body"><dl><dt>VNL-Phase</dt><dd>{esc(player['phase'])}</dd><dt>Matchdatensätze</dt><dd>{esc(player['matches'])}</dd><dt>Punkte</dt><dd>{esc(player['points'])}</dd><dt>Rolle</dt><dd>{esc(player['role'])}</dd></dl><p>{esc(player['text'])}</p>{source}</div>
        </details>''')
    return "\n".join(cards)


def build(data: dict) -> str:
    s = data["summary"]
    weeks = data["weeks"]
    game_filters = ''.join(f'<button type="button" data-game-filter="{esc(w["id"])}">{esc(w["label"])}</button>' for w in weeks)
    week_cards = ''.join(f'<article class="analysis-card {"positive" if w.get("featured") else ""}"><span>{esc(w['place'])} · {esc(w['date'])} · {esc(w['record'])}</span><h3>{esc(w["title"])}</h3><p>{esc(w["analysis"])}</p></article>' for w in weeks)
    return f'''<!doctype html>
<html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="description" content="Detaillierte Auswertung der deutschen Frauen-Nationalmannschaft in der Volleyball Nations League 2026 mit allen Spielen, Satzergebnissen, VNL-Finals und den aktuellen Bundesliga-Spielerinnen.">
<title>DVV Frauen-Nationalteam – VNL 2026 | Auswertung</title>
<style>
:root{{--black:#0b0b0f;--red:#c90018;--gold:#ffce00;--paper:#fffaf0;--muted:#626672;--line:rgba(11,11,15,.14);--green:#087443;--radius:24px;--shadow:0 16px 42px rgba(0,0,0,.12)}}*{{box-sizing:border-box}}html{{scroll-behavior:smooth}}body{{margin:0;color:var(--black);background:radial-gradient(circle at 8% 0,rgba(255,206,0,.25),transparent 25%),radial-gradient(circle at 92% 8%,rgba(201,0,24,.16),transparent 27%),#f8f8f8;font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;line-height:1.55}}a{{color:#870012}}a:focus-visible,button:focus-visible,summary:focus-visible{{outline:3px solid var(--gold);outline-offset:3px}}.wrap{{width:min(1180px,calc(100% - 32px));margin:auto}}nav{{position:sticky;top:0;z-index:10;background:rgba(11,11,15,.95);box-shadow:0 8px 24px #0004}}.nav-inner{{display:flex;gap:8px;overflow-x:auto;padding:8px 0;scrollbar-width:none}}nav a{{flex:none;padding:7px 11px;border:1px solid #ffffff30;border-radius:999px;color:white;text-decoration:none;font-size:.8rem;font-weight:800}}header{{color:white;background:linear-gradient(135deg,#000 0 58%,#c90018 58% 79%,#ffce00 79%);padding:64px 0 50px}}.eyebrow,.pill{{display:inline-flex;border:1px solid #ffffff45;border-radius:999px;background:#ffffff18;padding:8px 12px;font-weight:850}}h1{{max-width:900px;margin:18px 0 12px;font-size:clamp(2.4rem,7vw,5.2rem);line-height:.95;letter-spacing:-.06em}}.lead{{max-width:900px;font-size:clamp(1rem,2vw,1.25rem)}}.pills{{display:flex;flex-wrap:wrap;gap:8px;margin-top:22px}}main{{padding:30px 0 60px}}section{{scroll-margin-top:64px;margin:24px 0}}.block{{position:relative;overflow:hidden;background:#ffffffed;border:1px solid var(--line);border-radius:var(--radius);padding:clamp(20px,4vw,34px);box-shadow:var(--shadow)}}.block::before,.player::before{{content:"";position:absolute;inset:0 0 auto;height:7px;background:linear-gradient(90deg,#000 33%,var(--red) 33% 66%,var(--gold) 66%)}}h2{{margin:0 0 12px;font-size:clamp(1.65rem,4vw,2.45rem);letter-spacing:-.04em}}h3{{margin:.25rem 0}}.hero-stat{{display:grid;grid-template-columns:.8fr 1.2fr;gap:22px;align-items:center}}.rank{{font-size:clamp(6rem,17vw,11rem);font-weight:1000;line-height:.8;letter-spacing:-.08em}}.stats{{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:22px}}.stat,.analysis-card,.final-card{{padding:17px;border:1px solid var(--line);border-radius:18px;background:white}}.stat b{{display:block;font-size:1.7rem}}.stat small,.muted{{color:var(--muted);font-weight:700}}.compare{{width:100%;border-collapse:collapse;margin:18px 0}}th,td{{padding:10px;text-align:left;border-bottom:1px solid var(--line)}}th{{background:#f3f0e8}}.filters{{display:flex;gap:8px;overflow-x:auto;margin:18px 0;padding:3px}}button{{border:1px solid var(--line);border-radius:999px;padding:9px 13px;background:white;font:inherit;font-weight:800;cursor:pointer;white-space:nowrap}}button.active{{color:white;background:var(--black)}}.games,.players{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}}.game{{border:1px solid var(--line);border-left:7px solid var(--red);border-radius:18px;background:white;padding:17px}}.game.win{{border-left-color:var(--green)}}.game.featured{{box-shadow:inset 0 0 0 2px var(--gold)}}.game-head{{display:flex;justify-content:space-between;gap:12px}}.week-tag{{color:var(--muted);font-size:.82rem;font-weight:850}}.score{{border-radius:999px;padding:4px 9px;color:white;background:var(--red)}}.win .score{{background:var(--green)}}.sets{{font-weight:900;font-variant-numeric:tabular-nums}}.analysis-grid,.final-grid,.conclusion-grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}}.analysis-card.positive{{background:#eafff3;border-color:#76bc94}}.callout{{margin:20px 0;padding:18px;border-left:7px solid var(--gold);background:#fff4c3;border-radius:12px;font-size:1.08rem}}.player{{position:relative;overflow:hidden;border:1px solid var(--line);border-radius:18px;background:white}}summary{{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:22px 18px 16px;cursor:pointer;list-style:none}}summary::-webkit-details-marker{{display:none}}summary small{{display:block;color:var(--muted)}}.plus{{font-size:1.7rem}}details[open] .plus{{transform:rotate(45deg)}}.player-body{{padding:0 18px 18px}}dl{{display:grid;grid-template-columns:130px 1fr;gap:7px 12px}}dt{{color:var(--muted);font-weight:800}}dd{{margin:0;font-weight:650}}.sources li{{margin:.5rem 0}}footer{{padding:26px;color:white;text-align:center;background:var(--black)}}.no-js-note{{font-size:.9rem;color:var(--muted)}}[hidden]{{display:none!important}}
@media(max-width:760px){{header{{background:linear-gradient(160deg,#000 0 72%,#c90018 72% 88%,#ffce00 88%)}}.hero-stat,.games,.players,.analysis-grid,.final-grid,.conclusion-grid{{grid-template-columns:1fr}}.stats{{grid-template-columns:repeat(2,1fr)}}.block{{border-radius:18px}}.rank{{font-size:7rem}}dl{{grid-template-columns:1fr}}dd{{margin-bottom:7px}}}}
</style></head><body>
<nav aria-label="Sprungnavigation"><div class="wrap nav-inner"><a href="#start">Start</a><a href="#bilanz">Bilanz</a><a href="#spiele">Spiele</a><a href="#analyse">Analyse</a><a href="#finals">Finals</a><a href="#bundesliga">Bundesliga</a><a href="#muenster">Münster</a><a href="#fazit">Fazit</a><a href="#quellen">Quellen</a></div></nav>
<header id="start"><div class="wrap"><span class="eyebrow">DVV-Frauen · Volleyball Nations League {data['year']}</span><h1>VNL {data['year']}: Deutschland in der Detailanalyse</h1><p class="lead">Die Fortsetzung der Münster-Übersicht vom Mai: alle zwölf deutschen VNL-Spiele mit Satzergebnissen, die entscheidenden Trends der drei Turnierwochen, das Final Eight und die Einsatzrollen der Spielerinnen, die 2026/27 in der deutschen Volleyball-Bundesliga spielen.</p><div class="pills"><span class="pill">Stand: {esc(data['updated'])}</span><span class="pill">12 Vorrundenspiele</span><span class="pill">5 Siege · 7 Niederlagen</span><span class="pill">Final Eight verpasst</span></div></div></header>
<main class="wrap"><section id="bilanz" class="block"><div class="hero-stat"><div><div class="rank">{s['rank']}.</div><strong>Platz in der Vorrunde</strong><p>{s['points']} Punkte · {s['sets']} Sätze</p></div><div><h2>VNL-Gesamtbilanz</h2><p><strong>{s['ball_points']} Ballpunkte – nur {s['ball_difference']} über zwölf Spiele.</strong> Der zwölfte Platz bedeutet nicht, dass Deutschland durchgehend deutlich schlechter war. Verlorene enge Satzenden und Tiebreaks waren ein wesentlicher Faktor.</p></div></div><div class="stats"><div class="stat"><b>12.</b><small>von 18 Teams</small></div><div class="stat"><b>5</b><small>Siege aus 12</small></div><div class="stat"><b>7</b><small>Niederlagen, 3 im Tiebreak</small></div><div class="stat"><b>17</b><small>Tabellenpunkte</small></div><div class="stat"><b>21:25</b><small>Sätze</small></div><div class="stat"><b>−3</b><small>Ballpunktdifferenz</small></div></div><p>Die Münster-Länderspiele gegen die Niederlande eröffneten im Mai den Sommer; danach folgten Québec, Ankara und Belgrad. <a href="https://volleyball-streaming-ms.de/dvv_laenderspiele_20260516.html">Zur ursprünglichen Länderspielseite Münster 2026</a>.</p>
<h3>Vergleich 2025 zu 2026</h3><div style="overflow-x:auto"><table class="compare"><thead><tr><th>Kategorie</th><th>2025</th><th>2026</th></tr></thead><tbody><tr><th>Siege</th><td>7</td><td>5</td></tr><tr><th>Punkte</th><td>23</td><td>17</td></tr><tr><th>Platz</th><td>7</td><td>12</td></tr><tr><th>Final Eight</th><td>erreicht</td><td>verpasst</td></tr></tbody></table></div><p>Ergebnisorientiert war 2026 ein Rückschritt. Die nahezu ausgeglichene Ballpunktbilanz und Resultate gegen spätere Final-Four-Teams zeigen zugleich ein phasenweise besseres Leistungsniveau, als Platz zwölf vermuten lässt.</p></section>
<section id="spiele" class="block"><h2>Alle zwölf deutschen VNL-Spiele</h2><p class="no-js-note">Alle Satzergebnisse aus deutscher Sicht. Ohne JavaScript bleiben sämtliche Spiele sichtbar.</p><div class="filters" aria-label="Spiele nach Woche filtern"><button class="active" type="button" data-game-filter="all">Alle Spiele</button>{game_filters}</div><div class="games">{render_games(weeks)}</div></section>
<section id="analyse" class="block"><h2>Analyse der drei VNL-Wochen</h2><div class="analysis-grid">{week_cards}</div><h3 style="margin-top:28px">Enge Spiele und Tiebreaks</h3><div class="final-grid"><div class="final-card"><b>Ukraine · 13:15</b><p>Nach 0:2 zurückgekommen, knapp verloren.</p></div><div class="final-card"><b>China · 6:15</b><p>Nach 2:1-Führung früh den Anschluss verloren.</p></div><div class="final-card"><b>Türkiye · 13:15</b><p>Nach 2:0-Führung und 12:11 noch verloren.</p></div><div class="final-card"><b>Brasilien · 16:14</b><p>Die enge Partie gegen ein Spitzenteam erfolgreich geschlossen.</p></div></div><div class="callout"><strong>Deutschland verlor drei seiner vier Fünfsatzspiele.</strong> Closing und Konsequenz in entscheidenden Satzphasen waren zentrale Faktoren der Endplatzierung.</div></section>
<section id="finals" class="block"><h2>Final Eight · 22.–26. Juli 2026 in Macao</h2><p><strong>East Asian Games Dome · Macao, China.</strong> Deutschland war nicht qualifiziert. Als Gastgeber war China automatisch gesetzt; hinzu kamen die sieben besten Teams der Vorrunde. Deshalb war nicht Platz acht, sondern die Niederlande auf Platz sieben mit 21 Punkten der letzte reguläre Qualifikationsplatz. Deutschland fehlten mit 17 Punkten vier Punkte. China wurde Neunter und nahm über das Gastgeber-Ticket dennoch teil.</p><div class="final-grid"><div class="final-card"><b>Top 4</b><ol><li>Türkiye</li><li>Brasilien</li><li>Italien</li><li>China</li></ol></div><div class="final-card"><b>Halbfinals</b><p>Brasilien – Italien 3:2<br>Türkiye – China 3:0</p><b>Platz drei</b><p>Italien – China 3:1</p></div><div class="final-card"><b>Finale · 26. Juli · Türkiye – Brasilien 3:1</b><p class="sets">23:25 · 25:23 · 26:24 · 25:21</p><p>Türkiye gewann die VNL 2026.</p></div></div><div class="callout"><strong>Gegen China 2:3 · Türkiye 2:3 · Brasilien 3:2.</strong><br>Gesamt: 1 Sieg, 2 Niederlagen und <strong>7:8 Sätze</strong>. Das Spitzenleistungsniveau war phasenweise Final-Eight- oder Final-Four-tauglich; es fehlte die Konstanz über die komplette Vorrunde.</div></section>
<section id="bundesliga" class="block"><h2>Aktuelle Bundesliga-Spielerinnen</h2><p><strong>7 Spielerinnen: 4 Dresden · 2 Schwerin · 1 Suhl.</strong> „Matchdatensätze“ bedeutet, dass eine Spielerin in einem offiziellen Matchdatensatz geführt wurde – nicht, dass sie einen bestimmten Einsatzanteil hatte. Deshalb werden keine erfundenen Einsatzprozente angegeben. Bei Liberas sind Punkte ausdrücklich kein sinnvoller Leistungsmaßstab.</p><div class="filters" aria-label="Spielerinnen nach Verein filtern"><button class="active" type="button" data-club-filter="all">Alle</button><button type="button" data-club-filter="Dresdner SC">Dresdner SC</button><button type="button" data-club-filter="SSC Palmberg Schwerin">SSC Palmberg Schwerin</button><button type="button" data-club-filter="VfB Suhl LOTTO Thüringen">VfB Suhl</button><button type="button" id="toggle-profiles">Alle Profile aufklappen</button></div><div class="players">{render_players(data['players'])}</div><div class="callout">Die auffälligsten aktuellen Bundesliga-Spielerinnen waren <strong>Sarah Straube</strong> in zentraler Zuspielrolle und <strong>Lena Kindermann</strong> mit wachsender Verantwortung und 52 Punkten. Besonders Dresden profitiert von diesen Erfahrungen.</div></section>
<section id="muenster" class="block"><h2>Der Münster-Bezug nach der VNL</h2><p><strong>Emilia Jordan</strong> gehörte beim Lehrgang und den Mai-Länderspielen in Münster zum erweiterten Umfeld, wurde für die drei VNL-Wochen aber nicht in die Matchkader übernommen. Damit hatte der USC in der VNL 2026 keine aktuell beim USC spielende deutsche Nationalspielerin im Matchkader. Jordan steht 2026/27 weiter beim USC unter Vertrag.</p><div class="final-grid"><div class="final-card"><b>Mia Kirchhoff</b><p>VCO Münster · USC Münster · aktuell Schwerin</p></div><div class="final-card"><b>Lina Alsmeier</b><p>Ehemalige USC-Spielerin; Nationalmannschaftsdebüt 2019 in Münster.</p></div><div class="final-card"><b>Weitere Verbindungen</b><p>Emilia Weske ist in Münster geboren. Hanna Orthmann wurde im Münsteraner Umfeld am Pascal-Gymnasium und USC-Internat ausgebildet.</p></div></div></section>
<section id="fazit" class="block"><h2>Gesamtfazit</h2><div class="conclusion-grid"><article class="analysis-card"><h3>Ergebnisorientiert: Rückschritt</h3><p>Platz 12, fünf Siege, 17 Punkte und das verpasste Final Eight. Besonders teuer: die 2:3 gegen Ukraine und Türkiye sowie das 0:3 gegen die Niederlande.</p></article><article class="analysis-card positive"><h3>Leistungsorientiert: näher an der Spitze</h3><p>Ein Sieg gegen Finalist Brasilien, knappe Niederlagen gegen Champion Türkiye und den Vierten China, 7:8 Sätze gegen diese drei Teams sowie 1011:1014 Ballpunkte insgesamt.</p></article><article class="analysis-card"><h3>Schlussfolgerung</h3><p>Hohe internationale Qualität war über längere Phasen vorhanden. Hauptprobleme waren Konstanz, die Qualität im ersten und zweiten Kontakt sowie die Verwertung entscheidender Satz- und Spielphasen. Stabilere Annahme und ein besserer erster Kontakt müssen häufiger in einen geordneten Spielaufbau münden; erfolgreiche Abwehraktionen gilt es konsequenter in wirksame Gegenangriffe umzusetzen.</p></article></div></section>
<section id="quellen" class="block sources"><h2>Quellen &amp; Datenbasis</h2><ul><li><a href="https://volleyball-streaming-ms.de/dvv_laenderspiele_20260516.html">Ursprüngliche Münster-Seite</a></li><li><a href="https://en.volleyballworld.com/volleyball/competitions/volleyball-nations-league/">Volleyball World – VNL</a></li><li><a href="https://en.volleyballworld.com/volleyball/competitions/volleyball-nations-league/standings/women/">Volleyball World – Tabellen</a></li><li><a href="https://en.volleyballworld.com/volleyball/competitions/volleyball-nations-league/schedule/">Volleyball World – Spielplan und Ergebnisse</a></li><li><a href="https://www.volleyball-bundesliga.de/cms/home/1_bundesliga_frauen/teams_spielerinnen/wechselboerse.xhtml">VBL-Wechselbörse – letztes Update 10.08.2026</a></li><li><a href="https://www.volleyball-verband.de/">Deutscher Volleyball-Verband</a></li><li><a href="https://www.volleyball-verband.de/de/halle/top-events/volleyball-nations-league/">DVV – VNL-Spielberichte und Informationen</a> (Ukraine, Türkiye, Brasilien, Niederlande und Bulgarien)</li><li><a href="https://en.volleyballworld.com/volleyball/competitions/volleyball-nations-league/competition/">Volleyball World – Wettbewerb und Qualifikationsmodus</a></li></ul><p class="muted">Redaktioneller Datenstand: {esc(data['updated'])}. Die jährlich manuell zu pflegende Datenbasis liegt in <code>docs/data/dvv_vnl_2026.json</code>; diese HTML-Datei wird daraus ohne Laufzeit-API erzeugt.</p></section></main>
<footer>© 2026 Niels Westphal</footer><script>
document.querySelectorAll('[data-game-filter]').forEach(b=>b.addEventListener('click',()=>{{document.querySelectorAll('[data-game-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.game').forEach(x=>x.hidden=b.dataset.gameFilter!=='all'&&x.dataset.week!==b.dataset.gameFilter)}}));
document.querySelectorAll('[data-club-filter]').forEach(b=>b.addEventListener('click',()=>{{document.querySelectorAll('[data-club-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.player').forEach(x=>x.hidden=b.dataset.clubFilter!=='all'&&x.dataset.club!==b.dataset.clubFilter)}}));
const toggle=document.querySelector('#toggle-profiles');toggle.addEventListener('click',()=>{{const cards=[...document.querySelectorAll('.player:not([hidden])')],open=!cards.every(x=>x.open);cards.forEach(x=>x.open=open);toggle.textContent=open?'Alle Profile zuklappen':'Alle Profile aufklappen'}});
</script></body></html>'''


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--data", type=Path, default=DEFAULT_DATA)
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    args = parser.parse_args()
    data = json.loads(args.data.read_text(encoding="utf-8"))
    if sum(len(week["games"]) for week in data["weeks"]) != 12:
        raise ValueError("Die Datenbasis muss genau zwölf Spiele enthalten.")
    if len(data["players"]) != 7:
        raise ValueError("Die Datenbasis muss genau sieben Bundesliga-Spielerinnen enthalten.")
    args.output.write_text(build(data), encoding="utf-8")


if __name__ == "__main__":
    main()
